-- 126: Original BrillaPrep WASSCE BrillaPrep IRS beta content blueprint beta questions, part 5.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_126_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_126_guard;
INSERT INTO _migration_126_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_021' AND NOT (q.topic_id IS 'topic_was_irs_5' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When is tayammum permitted?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. When water is unavailable or its use would cause genuine harm","B. Whenever a person wishes to avoid all preparation","C. Only after completing the prayer","D. When clean water is freely available and safe"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Tayammum is a lawful dry purification using clean earth under recognised necessity; it is not a convenience that replaces usable water without cause. Therefore the correct answer is A: When water is unavailable or its use would cause genuine harm.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_021' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_126_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_022' AND NOT (q.topic_id IS 'topic_was_irs_5' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which prayer is performed in congregation on Friday in place of the normal midday prayer for those obligated to attend?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Tahajjud","B. Jumu’ah","C. Witr","D. Janazah"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Jumu’ah includes a sermon and congregational prayer and has special communal significance in weekly Muslim worship. Therefore the correct answer is B: Jumu’ah.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_022' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_126_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_023' AND NOT (q.topic_id IS 'topic_was_irs_5' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of wudu before prayer?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A substitute for every ethical duty","B. A guarantee that no mistake can occur","C. Ritual purification and readiness for worship","D. A method of calculating Zakah"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Wudu uses prescribed washing to prepare for prayer, joining physical cleanliness with conscious spiritual readiness. Therefore the correct answer is C: Ritual purification and readiness for worship.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_023' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_126_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_024' AND NOT (q.topic_id IS 'topic_was_irs_5' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'During which month is the obligatory fast observed?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Muharram only","B. Rabi al-Awwal","C. Dhu al-Qadah","D. Ramadan"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Fasting Ramadan is a pillar of Islam and trains self-restraint, gratitude, devotion and awareness of people in need. Therefore the correct answer is D: Ramadan.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_024' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_126_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_025' AND NOT (q.topic_id IS 'topic_was_irs_5' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the qiblah?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The direction of the Ka’bah faced during prayer","B. The sermon delivered after every meal","C. The charity due on crops","D. The chain of a Hadith"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Facing the qiblah unifies worshippers in direction while prayer remains directed to Allah rather than to the building itself. Therefore the correct answer is A: The direction of the Ka’bah faced during prayer.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_025' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
